'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { formatCurrency } from '@/lib/utils';
import { ShoppingCartIcon, PlusIcon, MagnifyingGlassIcon } from '@heroicons/react/24/outline';

// Mock POS data
const mockProducts = [
  { id: '1', name: 'Wireless Mouse Pro', price: 29.99, stock: 45, category: 'Electronics' },
  { id: '2', name: 'Mechanical Keyboard', price: 89.99, stock: 12, category: 'Electronics' },
  { id: '3', name: 'USB-C Cable', price: 12.99, stock: 156, category: 'Accessories' },
];

const mockCategories = ['All', 'Electronics', 'Accessories', 'Office', 'Storage'];

export default function POSPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [cart, setCart] = useState([]);
  const [total, setTotal] = useState(0);

  const addToCart = (product) => {
    setCart(prev => [...prev, { ...product, quantity: 1 }]);
    setTotal(prev => prev + product.price);
  };

  const removeFromCart = (index) => {
    const item = cart[index];
    setCart(prev => prev.filter((_, i) => i !== index));
    setTotal(prev => prev - item.price);
  };

  const filteredProducts = mockProducts.filter(product => {
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* POS Header */}
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-primary">Point of Sale</h1>
              <p className="text-sm text-text-secondary">Process sales and manage inventory</p>
            </div>
            <div className="flex items-center space-x-4">
              <div className="text-right">
                <p className="text-sm text-text-secondary">Cart Total</p>
                <p className="text-xl font-bold text-primary">{formatCurrency(total)}</p>
              </div>
              <div className="relative">
                <ShoppingCartIcon className="h-8 w-8 text-primary" />
                <span className="absolute -top-2 -right-2 h-5 w-5 bg-error rounded-full flex items-center justify-center text-xs text-white">
                  {cart.length}
                </span>
              </div>
            </div>
          </div>

          {/* Search and Filters */}
          <div className="card p-4">
            <div className="flex flex-col lg:flex-row gap-4">
              <div className="flex-1">
                <div className="relative">
                  <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-text-secondary" />
                  <input
                    type="text"
                    placeholder="Search products..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="input-field pl-10 w-full"
                  />
                </div>
              </div>
              <div className="flex gap-2">
                {mockCategories.map(category => (
                  <button
                    key={category}
                    onClick={() => setSelectedCategory(category)}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                      selectedCategory === category
                        ? 'bg-primary text-white'
                        : 'bg-surface text-primary hover:bg-divider'
                    }`}
                  >
                    {category}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Products Grid */}
            <div className="lg:col-span-2 space-y-4">
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                {filteredProducts.map(product => (
                  <div key={product.id} className="card p-4 hover-lift cursor-pointer">
                    <div className="space-y-3">
                      <div className="h-24 bg-surface rounded-lg flex items-center justify-center">
                        <span className="text-2xl text-text-secondary">📦</span>
                      </div>
                      <div>
                        <h3 className="font-medium text-primary text-sm">{product.name}</h3>
                        <p className="text-xs text-text-secondary">{product.category}</p>
                        <div className="flex items-center justify-between mt-2">
                          <span className="text-lg font-bold text-primary">{formatCurrency(product.price)}</span>
                          <span className={`text-xs px-2 py-1 rounded ${
                            product.stock > 20 ? 'bg-success/10 text-success' :
                            product.stock > 5 ? 'bg-warning/10 text-warning' :
                            'bg-error/10 text-error'
                          }`}>
                            {product.stock} in stock
                          </span>
                        </div>
                      </div>
                      <button
                        onClick={() => addToCart(product)}
                        className="w-full btn-primary flex items-center justify-center space-x-2"
                      >
                        <PlusIcon className="h-4 w-4" />
                        <span>Add to Cart</span>
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Cart */}
            <div className="space-y-4">
              <div className="card p-4">
                <h2 className="text-lg font-medium text-primary mb-4">Shopping Cart</h2>
                {cart.length === 0 ? (
                  <div className="text-center py-8">
                    <ShoppingCartIcon className="h-12 w-12 text-text-secondary mx-auto mb-2" />
                    <p className="text-text-secondary">Cart is empty</p>
                  </div>
                ) : (
                  <div className="space-y-3">
                    {cart.map((item, index) => (
                      <div key={index} className="flex items-center justify-between p-3 bg-surface rounded-lg">
                        <div className="flex-1">
                          <p className="text-sm font-medium text-primary">{item.name}</p>
                          <p className="text-xs text-text-secondary">Qty: {item.quantity}</p>
                        </div>
                        <div className="flex items-center space-x-2">
                          <span className="text-sm font-medium text-primary">{formatCurrency(item.price)}</span>
                          <button
                            onClick={() => removeFromCart(index)}
                            className="p-1 text-error hover:bg-error/10 rounded"
                          >
                            <PlusIcon className="h-4 w-4 rotate-45" />
                          </button>
                        </div>
                      </div>
                    ))}
                    <div className="border-t border-divider pt-3">
                      <div className="flex items-center justify-between">
                        <span className="font-medium text-primary">Total:</span>
                        <span className="text-lg font-bold text-primary">{formatCurrency(total)}</span>
                      </div>
                      <PlusIcon className="h-4 w-4" />
                      <span>Add to Cart</span>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </Layout>
    </AuthGuard>
  );
}
